import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"로컬 모델","description":"PC에서 Ollama / LM Studio / A1111 / ComfyUI 실행 후, 폰 MiniTavern을 LAN(BYOK)으로 연결. 로컬 LLM·이미지 입문.","frontmatter":{"title":"로컬 모델","description":"PC에서 Ollama / LM Studio / A1111 / ComfyUI 실행 후, 폰 MiniTavern을 LAN(BYOK)으로 연결. 로컬 LLM·이미지 입문.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"로컬 모델 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"PC에서 Ollama / LM Studio / A1111 / ComfyUI 실행 후, 폰 MiniTavern을 LAN(BYOK)으로 연결. 로컬 LLM·이미지 입문."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/local"}]]},"headers":[],"relativePath":"ko/local/index.md","filePath":"ko/local/index.md","lastUpdated":1787224147000}'),r={name:"ko/local/index.md"};function i(l,t,n,s,c,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="로컬-모델" tabindex="-1">로컬 모델 <a class="header-anchor" href="#로컬-모델" aria-label="Permalink to &quot;로컬 모델&quot;">​</a></h1><p>MiniTavern은 <strong>BYOK（직접 키 사용）</strong> 클라이언트입니다. 요청은 설정한 주소로 가며, 특정 클라우드에 강제되지 않습니다.<br> 「로컬 모델」은 <strong>본인 PC</strong>에서 추론 서비스를 돌리고, 폰의 MiniTavern으로 LAN 연결하는 것입니다.</p><p>두 갈래:</p><table tabindex="0"><thead><tr><th>유형</th><th>용도</th><th>입구</th></tr></thead><tbody><tr><td><strong>언어 모델</strong></td><td>채팅, 이어쓰기, 이미지 프롬프트 변환</td><td><a href="/ultra_guides/ko/quickstart">30분 퀵스타트</a> · <a href="./tools">도구 개요</a></td></tr><tr><td><strong>이미지 모델</strong></td><td><code>/imagine</code>, 첨부 이미지, 배경</td><td><a href="./image-gen/">이미지 개요</a></td></tr></tbody></table><p>GPU가 없고 서비스도 설치하기 싫다면 먼저 <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a> 체험/무료 한도.</p><blockquote><p>MiniTavern은 <strong>폰에서 대형 LLM이나 확산 모델을 실행하지 않습니다</strong>. 서비스는 PC, App은 캐릭터 카드·월드북·채팅·이미지 요청을 담당합니다.</p></blockquote><h2 id="언어-모델" tabindex="-1">언어 모델 <a class="header-anchor" href="#언어-모델" aria-label="Permalink to &quot;언어 모델&quot;">​</a></h2><p>PC에서 LLM（Ollama, LM Studio, KoboldCPP 등）을 실행하고, App에서는 <strong>Custom (OpenAI)</strong> 를 선택합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>권장</th></tr></thead><tbody><tr><td>PC</td><td>Windows / macOS / Linux; 메모리 <strong>16GB+</strong> 권장</td></tr><tr><td>GPU（선택）</td><td>NVIDIA / Apple Silicon이 더 빠름; CPU만으로도 가능</td></tr><tr><td>네트워크</td><td>폰과 PC를 <strong>같은 Wi‑Fi</strong>（게스트 격리망 금지）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>도구</th><th>적합한 사람</th><th>기본 포트</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/ollama/install">Ollama</a></td><td>CLI로 간편, 명령으로 모델 받기</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/ko/lmstudio/install">LM Studio</a></td><td>GUI, 클릭 다운로드</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/ko/koboldcpp/install">KoboldCPP</a></td><td>롤플레이 커뮤니티 정석</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/ko/llamacpp/install">llama.cpp</a></td><td>GGUF 직접 실행</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/ko/localai/install">LocalAI</a></td><td>Docker / 호환 레이어</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/ko/jan/install">Jan</a> · <a href="/ultra_guides/ko/textgen/install">text-generation-webui</a></td><td>기타 GUI / 플러그인</td><td>각 페이지</td></tr></tbody></table><p>추천 순서: <a href="/ultra_guides/ko/quickstart">퀵스타트</a> → <a href="./tools">도구</a> → <a href="./models">추천 모델</a> → <a href="/ultra_guides/ko/connect-app/minitavern">MiniTavern 설정</a> → 막히면 <a href="/ultra_guides/ko/troubleshoot">문제 해결</a>.</p><h2 id="이미지-모델" tabindex="-1">이미지 모델 <a class="header-anchor" href="#이미지-모델" aria-label="Permalink to &quot;이미지 모델&quot;">​</a></h2><p>PC에서 Stable Diffusion 계열 실행. App <strong>설정 → 이미지 생성 → 이미지 연결</strong>에서 A1111 또는 ComfyUI.</p><table tabindex="0"><thead><tr><th>백엔드</th><th>기본 포트</th><th>튜토리얼</th></tr></thead><tbody><tr><td><a href="./image-gen/a1111">A1111 / SD WebUI</a></td><td><code>7860</code></td><td><code>--api --listen</code> 필요</td></tr><tr><td><a href="./image-gen/comfyui">ComfyUI</a></td><td><code>8188</code>（Desktop은 <code>8000</code> 흔함）</td><td><code>--listen</code> 필요</td></tr></tbody></table><p>개요·하드웨어: <a href="./image-gen/">이미지 모델 배포</a>; 연결 입력: <a href="./image-gen/connect-app">App 연결</a>.</p><h2 id="중요-안내" tabindex="-1">중요 안내 <a class="header-anchor" href="#중요-안내" aria-label="Permalink to &quot;중요 안내&quot;">​</a></h2><ul><li>폰에는 PC의 <strong>LAN IP</strong>를 넣으세요. <code>localhost</code> / <code>127.0.0.1</code>은 <strong>불가</strong>.</li><li>언어 모델 Base URL은 보통 <code>/v1</code>로 끝남（예 <code>http://192.168.1.8:11434/v1</code>）.</li><li>A1111은 <code>--api</code> 필수; ComfyUI는 LAN에서 도달 가능해야 함.</li><li>방화벽에서 포트 개방; 인증 없는 API를 <strong>공용 인터넷에 노출하지 말 것</strong>.</li></ul>',17)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
